Deno.serve(async (req) => {
  const base44 = createClientFromRequest(req);
  const user = await base44.auth.me().catch(() => null);
  if (!user) return Response.json({ error: 'auth required' }, { status: 401 });
  const svc = base44.asServiceRole.entities as Record<string, any>;
  const out: Record<string, any> = {};
  let ok = true;
  for (const [entity, exp] of Object.entries(EXPECTED)) {
    let rows: any[] = [];
    let defined = true;
    try {
      let skip = 0, lastFirst: string | null = null;
      for (let i = 0; i < 100; i++) {
        let page: any[];
        try { page = await svc[entity].list('game_id', 1000, skip); } catch { page = await svc[entity].list('game_id', 1000); }
        if (!page || page.length === 0) break;
        if (page[0]?.id && page[0].id === lastFirst) break;
        lastFirst = page[0]?.id ?? null;
        rows.push(...page);
        if (page.length < 1000) break;
        skip += page.length;
      }
    } catch { defined = false; }
    const liveIds = new Set(rows.map((r) => r.game_id).filter(Boolean));
    const missing = exp.keyed ? exp.ids.filter((id) => !liveIds.has(id)) : [];
    const extra = exp.keyed ? [...liveIds].filter((id) => !exp.ids.includes(id)) : [];
    const builds = [...new Set(rows.map((r) => r.game_build).filter(Boolean))];
    const state = !defined ? 'missing_entity' : rows.length === 0 ? 'empty'
      : (exp.keyed ? missing.length === 0 && extra.length === 0 : rows.length === exp.count) && builds.length === 1 && builds[0] === GAME.buildid ? 'synced'
      : builds.some((b) => b !== GAME.buildid) ? 'stale' : 'partial';
    if (state !== 'synced') ok = false;
    out[entity] = { expected: exp.count, live: rows.length, live_build: builds.join('|') || null, missing: missing.slice(0, 50), extra: extra.slice(0, 50), state };
  }
  return Response.json({ game: GAME, entities: out, ok });
});
